package cn.lili.common.security.session;
import cn.lili.modules.community.p0.support.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static cn.lili.common.security.session.Stage1PersistenceTest.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@EnabledIfSystemProperty(named="s1.integration",matches="owned-run")
@Timeout(value=7,unit=TimeUnit.MINUTES)
class Stage1FulfillmentCoverageTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh()throws Exception{new Stage1SupplyMatrixTest().refresh();}
    @Test void openingHoursAreInstructionsAndAddressRangesFeesRemainPerStoreConfiguration()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var pointInput=Stage1BusinessBoundaryTest.pointBody();pointInput.add("opening",object(map("weekdays",List.of(LocalDate.now(Stage1Rules.ZONE).getDayOfWeek().getValue()%7+1),"allDay",false,"start","09:00","end","17:00","crossDay",false)));String pickup=call(post(Stage1Routes.STORE+"/points"),owner.login().session(),pointInput,200).get("id").getAsString(),other=createPointFixture(owner,"COMMUNITY_PICKUP"),redemption=createPointFixture(owner,"STORE_REDEMPTION");for(String point:List.of(pickup,other,redemption))call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST完整点"),200);
        if(db.count("SELECT COUNT(*) FROM li_region WHERE ad_code='990102'")==0)db.update("INSERT INTO li_region(id,delete_flag,create_by,ad_code,level,name,parent_id,path) VALUES(719000000000000004,0,'S1_TEST','990102','district','S1_TEST排除区',719000000000000002,'719000000000000001,719000000000000002,719000000000000004')");
        var methods=object(deliveryMethods());methods.getAsJsonObject("MERCHANT_DELIVERY").addProperty("feeCent",500);methods.add("EXPRESS",object(map("enabled",true,"feeCent",800,"nationwide",true,"excludedDistrictCodes",List.of("990102"))));methods.getAsJsonObject("COMMUNITY_PICKUP").addProperty("enabled",true);methods.getAsJsonObject("STORE_REDEMPTION").addProperty("enabled",true);call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"methods",methods,"reason","S1_TEST完整交集"),200);
        var a=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("EXPRESS","MERCHANT_DELIVERY","COMMUNITY_PICKUP","STORE_REDEMPTION"),true);var b=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("EXPRESS","MERCHANT_DELIVERY","COMMUNITY_PICKUP"),true);var buyer=Stage1CrossHostTest.resident();var command=map("storeId",owner.store(),"items",List.of(map("skuId",Stage1CrossHostTest.sku(a),"quantity",2),map("skuId",Stage1CrossHostTest.sku(b),"quantity",3)),"method","COMMUNITY_PICKUP","pointId",pickup);
        var first=call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200);assertEquals("PASS",first.get("status").getAsString());assertEquals(2,first.getAsJsonObject("candidatePoints").getAsJsonArray("COMMUNITY_PICKUP").size());assertEquals(500,first.getAsJsonObject("feeConfigurations").getAsJsonObject("MERCHANT_DELIVERY").get("feeCent").getAsInt());assertEquals(800,first.getAsJsonObject("feeConfigurations").getAsJsonObject("EXPRESS").get("feeCent").getAsInt());assertFalse(first.toString().matches(".*(?:shippingOrderAmount|totalAmount|commissionCent|reservationId).*"));
        var changed=pointInput.deepCopy();changed.addProperty("requestId",req());changed.addProperty("expectedVersion",1);changed.addProperty("address","S1_TEST当前新地址");call(put(Stage1Routes.STORE+"/points/"+pickup),owner.login().session(),changed,200);var history=call(get(Stage1Routes.STORE+"/points/"+pickup),owner.login().session(),null,200);assertEquals(pointInput.get("address"),history.getAsJsonArray("history").get(1).getAsJsonObject().getAsJsonObject("snapshot").get("address"));assertEquals("S1_TEST当前新地址",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).getAsJsonObject("candidatePoints").getAsJsonArray("COMMUNITY_PICKUP").asList().stream().map(JsonElement::getAsJsonObject).filter(p->pickup.equals(p.get("id").getAsString())).findFirst().orElseThrow().get("address").getAsString());
        command.remove("pointId");for(String method:List.of("MERCHANT_DELIVERY","EXPRESS")){command.put("method",method);command.remove("address");assertEquals("INPUT_REQUIRED",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).get("status").getAsString());for(String district:List.of("990101","990102")){command.put("address",map("provinceCode","990000","cityCode","990100","districtCode",district));assertEquals(district.equals("990101")?"PASS":"BLOCKED",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).get("status").getAsString());}}
        for(String point:List.of(pickup,other))call(post(Stage1Routes.STORE+"/points/"+point+"/disable"),owner.login().session(),map("requestId",req(),"expectedVersion",point.equals(pickup)?2:1,"reason","S1_TEST依次停自提"),200);command.put("method","MERCHANT_DELIVERY");command.put("address",map("provinceCode","990000","cityCode","990100","districtCode","990101"));assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).get("status").getAsString());assertTrue((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));
        for(String code:List.of("VIRTUAL","SELF_PICK_UP","UNKNOWN")){command.put("method",code);call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,422);}command.put("method","MERCHANT_DELIVERY");command.put("autoSplit",true);call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,422);
        var contradiction=methods.deepCopy();contradiction.getAsJsonObject("EXPRESS").add("districtCodes",new Gson().toJsonTree(List.of("990101")));call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",2,"methods",contradiction,"reason","S1_TEST范围矛盾"),422);
    }
    @Test void concurrentPrechecksAreReadOnlyAcrossSqlRedisAndPersistentBusinessFacts()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var goods=Stage1SupplyMatrixTest.createGoods(owner,10,List.of("MERCHANT_DELIVERY"),true);var buyer=Stage1CrossHostTest.resident();var body=map("storeId",owner.store(),"items",List.of(map("skuId",Stage1CrossHostTest.sku(goods),"quantity",1)),"method","MERCHANT_DELIVERY","address",map("provinceCode","990000","cityCode","990100","districtCode","990101"));var before=Stage1SupplyMatrixTest.factCounts();var redisBefore=Stage1SupplyMatrixTest.redisFacts();var ready=new CountDownLatch(100);var go=new CountDownLatch(1);
        try(var executor=Executors.newFixedThreadPool(100)){var futures=new ArrayList<Future<JsonObject>>();for(int i=0;i<100;i++)futures.add(executor.submit(()->{ready.countDown();assertTrue(go.await(30,TimeUnit.SECONDS));forbidSqlWrites.set(true);try{return call(post(Stage1Routes.BUYER+"/precheck"),buyer,body,200);}finally{forbidSqlWrites.remove();}}));assertTrue(ready.await(30,TimeUnit.SECONDS));go.countDown();for(var future:futures){var result=future.get(90,TimeUnit.SECONDS);assertEquals("PASS",result.get("status").getAsString());assertFalse(result.toString().matches(".*(?:costCent|commissionCent|orderId|paymentId).*"));assertTrue(result.has("evaluatedAt"));assertTrue(result.has("sourceVersions"));}}
        assertEquals(before,Stage1SupplyMatrixTest.factCounts());assertEquals(redisBefore,Stage1SupplyMatrixTest.redisFacts());assertEquals(10,db.count("SELECT quantity FROM li_goods_sku WHERE id=?",Stage1CrossHostTest.sku(goods)));
    }
}
